alter table material_versions add column file_text_content text null;
create table upload_intents (id uuid primary key, user_id uuid not null references app_users(id), object_key varchar(600) not null unique, original_filename varchar(255) not null, mime_type varchar(160) not null, size_bytes bigint not null, checksum_sha256 varchar(64) not null, status varchar(16) not null, expires_at timestamp with time zone not null, created_at timestamp with time zone not null, consumed_at timestamp with time zone null, constraint ck_upload_intent_size check (size_bytes > 0));
create table file_assets (id uuid primary key, material_id uuid not null references materials(id), uploader_id uuid not null references app_users(id), upload_intent_id uuid not null unique references upload_intents(id), object_key varchar(600) not null unique, original_filename varchar(255) not null, mime_type varchar(160) not null, size_bytes bigint not null, checksum_sha256 varchar(64) not null, file_created_time timestamp with time zone not null);
create table version_files (version_id uuid not null references material_versions(id), file_id uuid not null references file_assets(id), display_order integer not null, primary key(version_id,file_id), constraint uq_version_file_order unique(version_id,display_order));
